let dashboardPowerExpanded=false;
function powerRankings(){
 return state.teams.filter(t=>!expansionPendingSeason(t)).map(club=>{
  const games=state.history.filter(g=>g.stage==='Regular season'&&(g.a===club.id||g.b===club.id)).slice().sort((a,b)=>b.day-a.day),recent=games.slice(0,10),gp=club.w+club.l,win=gp?club.w/gp:.5,lastWins=recent.filter(g=>g.winner===club.id).length,form=recent.length?lastWins/recent.length:win,mov=games.length?games.reduce((n,g)=>n+(g.a===club.id?g.sa-g.sb:g.sb-g.sa),0)/games.length:null,rating=strength(club),evidence=Math.min(1,gp/20),performance=win*.5+form*.3+(mov===null?.5:Math.max(0,Math.min(1,(mov+20)/40)))*.2;
  return {club,gp,rating,lastWins,lastLosses:recent.length-lastWins,recentGames:recent.length,mov,score:100*(rating/99*(1-.7*evidence)+performance*.7*evidence)};
 }).sort((a,b)=>b.score-a.score||b.rating-a.rating||a.club.id-b.club.id).map((r,i)=>({...r,rank:i+1}));
}
function gmPowerRankings(full=false){
 const rows=powerRankings(),own=rows.find(r=>r.club.id===controlledTeamId()),visible=full?rows:rows.filter(r=>r.rank<=5||r.club.id===controlledTeamId()),preseason=rows.every(r=>r.gp===0);
 return gmPanel('POWER RANKINGS',`<div class="power-summary"><strong>${own?'#'+own.rank+' / '+rows.length:'—'}</strong><span>${preseason?'Preseason projection':'Your league power rank'}</span></div><div class="scroll"><table class="power-table"><thead><tr><th>#</th><th>Move</th><th>Team</th><th>Record</th><th>L10</th><th>Power</th></tr></thead><tbody>${visible.map(r=>`<tr class="${r.club.id===controlledTeamId()?'your-team':''}"><td>${r.rank}</td><td>${powerMovementBadge(r)}</td><td><span class="power-team">${secondaryTeamLogo(r.club)}<span>${escapeHTML(r.club.city+' '+r.club.name)}${r.club.id===controlledTeamId()?' <small>YOU</small>':''}</span></span></td><td>${r.club.w}–${r.club.l}</td><td>${r.recentGames?r.lastWins+'–'+r.lastLosses:'—'}</td><td><strong>${r.score.toFixed(1)}</strong></td></tr>`).join('')}</tbody></table></div><button class="gm-panel-link" onclick="go('${full?'Overview':'Power rankings'}')">${full?'← Back to GM dashboard':'View full power rankings →'}</button><p class="power-method">Movement since the previous league day. Green ▲ up · Red ▼ down · — unchanged or no comparison yet.</p><details class="power-method"><summary>How rankings work</summary><p>Roster strength sets the preseason ranking. Results gradually carry more weight over the first 20 games. After that: 30% roster strength, 35% season win rate, 21% last-10 win rate, and 14% scoring margin (capped at ±20 points). Regular-season games only. Power scores run from 0–100; they are not championship probabilities.</p></details>`,'','gm-power');
}

function capturePowerRankings(){state.powerMovement={year:state.year,day:state.day+1,previous:powerRankings().map(r=>({id:r.club.id,rank:r.rank}))}}
function powerMovementBadge(row){const snapshot=state.powerMovement,old=snapshot?.year===state.year?snapshot.previous.find(r=>r.id===row.club.id):null,change=old?old.rank-row.rank:0;return change?`<span class="power-move ${change>0?'power-up':'power-down'}" aria-label="${change>0?'Up':'Down'} ${Math.abs(change)} places">${change>0?'▲':'▼'} ${Math.abs(change)}</span>`:'<span class="muted" aria-label="Unchanged or no comparison available">—</span>'}
function readPowerMovement(raw,bad,count,year){if(raw===undefined)return undefined;if(!raw||!Number.isInteger(raw.year)||raw.year<1900||raw.year>year||!Number.isInteger(raw.day)||raw.day<1||raw.day>366||!Array.isArray(raw.previous)||raw.previous.length>count||new Set(raw.previous.map(r=>r.id)).size!==raw.previous.length||new Set(raw.previous.map(r=>r.rank)).size!==raw.previous.length||raw.previous.some(r=>!Number.isInteger(r.id)||r.id<0||r.id>=count||!Number.isInteger(r.rank)||r.rank<1||r.rank>raw.previous.length))bad('invalid power ranking history');return {year:raw.year,day:raw.day,previous:raw.previous.map(r=>({id:r.id,rank:r.rank}))}}
